Open Scope Z_scope.
(* [comment removed for export] *)
Local Notation atot a := (atotal (aok a) (apost a)) (only parsing).
Local Notation STOTA := (STOT (St:=APS) nstepA (fun R0 => texit (R:=R0) nstepA nexit)).

