Theorem asan_ok_free : forall Y q n s mo,
  AI ((q, n) :: Y) s mo ->
  STOTA (afree_M q s) mo
        (fun _ s' mo' => AI Y s' mo' /\ aps_so s' = aps_so s /\ m_fds mo' = m_fds mo /\ m_fs mo' = m_fs mo
                       /\ a_next (aps_m s') = a_next (aps_m s)).
